#include <iostream>

int main() {
    int x = 3;
    int y = 2;

    // Dangling else resolution using explicit braces (Check Point 3.9)
    if (x > 2) {
        if (y > 2) {
            int z = x + y;
            std::cout << "z is " << z << "\n";
        }
    } else {
        std::cout << "x is " << x << "\n";
    }

    // Correct multi-way ordering (Check Point 3.11 fix)
    double score = 85.5;
    if (score >= 90.0) {
        std::cout << "Grade is A\n";
    } else if (score >= 80.0) {
        std::cout << "Grade is B\n";
    } else if (score >= 70.0) {
        std::cout << "Grade is C\n";
    } else if (score >= 60.0) {
        std::cout << "Grade is D\n";
    } else {
        std::cout << "Grade is F\n";
    }

    return 0;
}

